/**
 * ZAPROJEKTOWANI Suite — front fixes v2.2.228
 * FAQ: usuwa tryb FAQ headera i wymusza dokładnie tryb header/nav z Realizacji.
 * Nie dotyka hero FAQ, treści, kart, listy pytań ani JS FAQ.
 */
if (!defined('ABSPATH')) exit;

function zp_suite_228_is_faq_page(){
  if (is_admin()) return false;
  if (function_exists('is_page') && (is_page('faq') || is_page('najczesciej-zadawane-pytania'))) return true;
  if (function_exists('is_singular') && is_singular()) {
    $post_id = get_queried_object_id();
    $content = $post_id ? (string) get_post_field('post_content', $post_id) : '';
    if ($content && (has_shortcode($content, 'zp_faq_page') || has_shortcode($content, 'zp_page_faq'))) return true;
  }
  return false;
}

/* Najważniejsze: dla FAQ zdejmujemy klasy trybu FAQ i nadajemy klasy trybu Realizacji.
   Dzięki temu header łapie dokładnie ten sam rdzeń stylowania co /realizacje/. */
add_filter('body_class', function($classes){
  if (!zp_suite_228_is_faq_page()) return $classes;
  $classes = array_values(array_diff($classes, ['zp-faq-page','zp-faq-shortcode']));
  foreach (['zp-realizacje-page','zp-realizacje-shortcode','zp-faq-nav-as-realizacje'] as $c) {
    if (!in_array($c, $classes, true)) $classes[] = $c;
  }
  return $classes;
}, 2147483647);

